using System;
using System.Collections.Generic;
using System.ComponentModel;
using System.Drawing;
using System.Linq;
using System.Windows.Forms;
using MedGas2024.Core;
namespace MedGas2024.UI
{
    public sealed class DensityForm:Form
    {
        readonly BindingList<DensityRow> rows;readonly Func<DensityOptions,List<string>,List<DensityRow>> preview;readonly Func<DensityOptions,List<string>,int> apply;readonly Func<string> outcomeDetails;
        readonly DataGridView grid=new DataGridView{Name="DensityRows",Dock=DockStyle.Fill};readonly ComboBox mode=new ComboBox{Name="DensityMode",DropDownStyle=ComboBoxStyle.DropDownList,Width=220};
        readonly NumericUpDown multiplier=Number("DensityMultiplier",.01M,1000,2,3),paper=Number("DensityPaper",.1M,10000,100,2),scale=Number("DensityDenominator",1,100000,100,0);
        readonly TextBox status=new TextBox{Dock=DockStyle.Fill,Name="DensityStatus",Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Vertical};readonly Button commit=new Button{Name="DensityApply",Text="Áp dụng các dòng hợp lệ",AutoSize=true,Enabled=false};
        string reviewed;bool updating;List<string> reviewedSkipped=new List<string>();
        static NumericUpDown Number(string name,decimal min,decimal max,decimal value,int decimals){return new CompactNumber{Name=name,Minimum=min,Maximum=max,Value=value,DecimalPlaces=decimals,Width=92};}
        static void Field(FlowLayoutPanel p,string label,Control c){p.Controls.Add(new Label{Text=label,AutoSize=true,Margin=new Padding(6,7,4,0)});p.Controls.Add(c);}
        public DensityForm(List<DensityRow> data,Func<DensityOptions,List<string>,List<DensityRow>> inspect,Func<DensityOptions,List<string>,int> execute,Func<string> outcome=null)
        {UiTheme.Attach(this);
            rows=new BindingList<DensityRow>(data);preview=inspect;apply=execute;outcomeDetails=outcome;Text="Mr.T Mật độ chữ trên ống | 2.0.2.4";Font=UiStyle.Body();Size=new Size(1350,800);MinimumSize=new Size(1050,650);StartPosition=FormStartPosition.CenterParent;
            var root=new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(14),ColumnCount=1,RowCount=6};root.RowStyles.Add(new RowStyle(SizeType.Absolute,42));root.RowStyles.Add(new RowStyle(SizeType.Absolute,72));root.RowStyles.Add(new RowStyle(SizeType.Percent,100));root.RowStyles.Add(new RowStyle(SizeType.Absolute,68));root.RowStyles.Add(new RowStyle(SizeType.Absolute,46));root.RowStyles.Add(new RowStyle(SizeType.Absolute,24));Controls.Add(root);
            root.Controls.Add(new Label{Text="MẬT ĐỘ CHỮ TRÊN ỐNG MR.T",Font=UiStyle.Emphasis(18),Dock=DockStyle.Fill},0,0);
            var opts=new FlowLayoutPanel{Dock=DockStyle.Fill,WrapContents=true};mode.Items.AddRange(new object[]{"Nhân nhịp hiện tại","Ước tính khoảng trên giấy"});mode.SelectedIndex=0;Field(opts,"Cách chỉnh:",mode);Field(opts,"Nhịp ×",multiplier);Field(opts,"Khoảng giấy (mm)",paper);Field(opts,"Tỷ lệ in 1:",scale);root.Controls.Add(opts,0,1);
            UiStyle.Grid(grid);grid.ColumnHeadersHeightSizeMode=DataGridViewColumnHeadersHeightSizeMode.EnableResizing;grid.ColumnHeadersHeight=55;grid.AutoGenerateColumns=false;grid.AllowUserToAddRows=false;grid.AllowUserToDeleteRows=false;grid.RowHeadersVisible=false;grid.DataSource=rows;grid.AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill;
            grid.Columns.Add(new DataGridViewCheckBoxColumn{Name="Selected",DataPropertyName="Selected",HeaderText="Chọn",FillWeight=45,MinimumWidth=50});
            foreach(var def in new[]{new[]{"Layer","Layer","130"},new[]{"Type","Linetype","120"},new[]{"Scope","Phạm vi","65"},new[]{"Text","Chữ","75"},new[]{"Direct","Đường khớp","65"},new[]{"Nested","Trong block","60"},new[]{"Before","Chu kỳ trước","70"},new[]{"After","Chu kỳ sau","70"},new[]{"State","Tình trạng","100"},new[]{"Result","Xem trước / lý do","240"}})grid.Columns.Add(new DataGridViewTextBoxColumn{Name=def[0],DataPropertyName=def[0],HeaderText=def[1],FillWeight=Int32.Parse(def[2]),MinimumWidth=55,ReadOnly=true});
            grid.CurrentCellDirtyStateChanged+=delegate{if(grid.IsCurrentCellDirty)grid.CommitEdit(DataGridViewDataErrorContexts.Commit);};grid.CellValueChanged+=delegate{if(!updating)InvalidateReview();};grid.SelectionChanged+=delegate{var row=grid.CurrentRow==null?null:grid.CurrentRow.DataBoundItem as DensityRow;if(row!=null&&!String.IsNullOrEmpty(row.Result))status.Text="Chi tiết "+row.Layer+" / "+row.Type+": "+row.Result+"\r\nChọn nhóm khác để xem. Ước tính giấy phụ thuộc viewport/PSLTSCALE/MSLTSCALE.";};root.Controls.Add(grid,0,2);
            status.Text="Chỉ xử lý nét có tiền tố Mr.T_ / Mr.T.; phân biệt nét Theo layer và nét Gán riêng. Xref không sửa.\r\nNếu cùng nhóm có nhiều scale, nhóm phổ biến dùng nét layer và các scale khác gán nét riêng; giữ scale/chiều cao chữ. Đổi nét layer ảnh hưởng ByLayer trong block/Layout. Khoảng giấy chỉ ước tính Model mm, cần xem PDF/viewport.";root.Controls.Add(status,0,3);
            var buttons=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.RightToLeft};var close=new Button{Text="Đóng",AutoSize=true};close.Click+=delegate{Close();};buttons.Controls.Add(close);buttons.Controls.Add(commit);var check=new Button{Name="DensityPreview",Text="Xem trước",AutoSize=true};buttons.Controls.Add(check);var all=new Button{Text="Chọn dòng hợp lệ",AutoSize=true};buttons.Controls.Add(all);root.Controls.Add(buttons,0,4);root.Controls.Add(new Label{Text="workflow by Mr.Toan-NhiTW",Dock=DockStyle.Fill,TextAlign=ContentAlignment.MiddleRight},0,5);
            Action changed=delegate{multiplier.Enabled=mode.SelectedIndex==0;paper.Enabled=scale.Enabled=mode.SelectedIndex==1;InvalidateReview();};mode.SelectedIndexChanged+=delegate{changed();};multiplier.ValueChanged+=delegate{changed();};paper.ValueChanged+=delegate{changed();};scale.ValueChanged+=delegate{changed();};changed();
            all.Click+=delegate{updating=true;try{foreach(var r in rows)r.Selected=r.State=="Có thể xem trước";rows.ResetBindings();}finally{updating=false;}InvalidateReview();};
            check.Click+=delegate{try{grid.EndEdit();var opt=Options();var names=Names();var result=preview(opt,names);var lookup=result.ToDictionary(x=>x.Key,StringComparer.OrdinalIgnoreCase);updating=true;try{foreach(var row in rows){DensityRow r;if(lookup.TryGetValue(row.Key,out r)){row.Before=r.Before;row.After=r.After;row.Result=r.Result;}else{row.Before=row.After=row.Result="";}}rows.ResetBindings();}finally{updating=false;}reviewed=Key(opt,names);reviewedSkipped=result.Where(r=>r.After=="—").Select(r=>r.Layer+" / "+r.Type+": "+r.Result).ToList();int ok=result.Count(r=>r.After!="—"),notReady=rows.Count(r=>!r.Selected&&r.State!="Có thể xem trước");status.Text="Sẵn sàng: "+ok+" nhóm | Bỏ qua trong lựa chọn: "+reviewedSkipped.Count+" | Nhóm không hỗ trợ chưa chọn: "+notReady+". "+(reviewedSkipped.Count>0?"CÁC NHÓM BỊ BỎ SẼ KHÔNG ĐƯỢC ĐỒNG BỘ. "+String.Join(" | ",reviewedSkipped):"Chọn dòng để xem chi tiết.")+"\r\nƯớc tính giấy phụ thuộc viewport/PSLTSCALE/MSLTSCALE; block/Layout có thể chịu tác động ByLayer.";commit.Enabled=ok>0;}catch(Exception ex){InvalidateReview();MessageBox.Show(this,ex.Message,"Chưa xem trước");}};
            commit.Click+=delegate{try{grid.EndEdit();var opt=Options();var names=Names();if(reviewed!=Key(opt,names))throw new InvalidOperationException("Thông số hoặc lựa chọn đã đổi; hãy xem trước lại.");string skipped=reviewedSkipped.Count==0?"":"\r\n\r\nKHÔNG xử lý "+reviewedSkipped.Count+" nhóm:\r\n"+String.Join("\r\n",reviewedSkipped.Take(12))+(reviewedSkipped.Count>12?"\r\n... Xem bảng để đọc tất cả.":"");string mixed=opt.PaperMode?"\r\nNhóm có nhiều scale: scale phổ biến dùng nét layer, các scale khác được GÁN NÉT RIÊNG; giữ nguyên scale và cỡ chữ. Xem chi tiết từng dòng.":"";if(MessageBox.Show(this,"Áp dụng các dòng hợp lệ đã xem trước? Các đường ByLayer cùng layer, kể cả trong block/Layout, có thể thay đổi hiển thị. Các mẫu ống trong bảng Mr.T cũng sẽ được thử đồng bộ theo nguồn, giữ hệ số của bảng. Nên lưu bản sao DWG."+mixed+skipped,"Xác nhận mật độ chữ",MessageBoxButtons.YesNo,MessageBoxIcon.Question)!=DialogResult.Yes)return;int n=apply(opt,names);MessageBox.Show(this,"Đã xử lý "+n+" nhóm layer/nét; bỏ qua "+reviewedSkipped.Count+" nhóm đã chọn."+skipped+"\r\n"+(outcomeDetails==null?"":outcomeDetails())+"\r\nKiểm tra PDF/REGEN và dùng UNDO nếu cần.","Mr.T");InvalidateReview();Close();}catch(Exception ex){InvalidateReview();MessageBox.Show(this,ex.Message,"Chưa áp dụng");}};
        }
        void InvalidateReview(){reviewed=null;commit.Enabled=false;}
        DensityOptions Options(){return new DensityOptions{PaperMode=mode.SelectedIndex==1,Multiplier=(double)multiplier.Value,PaperMm=(double)paper.Value,Denominator=(double)scale.Value};}
        List<string> Names(){return rows.Where(r=>r.Selected).Select(r=>r.Key).OrderBy(s=>s,StringComparer.OrdinalIgnoreCase).ToList();}
        static string Key(DensityOptions o,List<string> names){return o.Signature+"|"+String.Join("|",names);}
    }
}
